            if (r.data.exists) {
              const lotNos = r.data.lot_nos || lot.lot_no || '?';
              setDupAlerts(prev => ({ ...prev, [catalogueId]: `⚠️ ${value.party_code} already marked for ${lot.garden}/${lot.grade} — Lots: ${lotNos}. Duplicate allowed.` }));
